import { test } from 'vitest';
import {
  DEFAULT_SIZE,
  PREFERENCES_KEY,
  PREFERENCES_VERSION,
  readPreferences,
  rememberBest,
  writePreferences,
} from './storage.ts';
import { MOVES_MAX } from '../game.ts';
